/* ===== ring ropes as a barrier in front of the crowd ===== */
const ROPES_SRC='data:image/webp;base64,';
(function(){const _vs=vShow;vShow=function(){const h=_vs.apply(this,arguments);
 try{if(h.indexOf('class="stage"')>=0)return h.replace('<img class="stg-crowd"','<img class="stg-crowd"').replace(/(<img class="stg-crowd"[^>]*>)(<\/div>)/,'$1<img class="stg-ropes" src="'+ROPES_SRC+'" alt="">$2')}catch(e){}return h};
 try{if(typeof document!=='undefined'&&!document.getElementById('ropescss')){const s=document.createElement('style');s.id='ropescss';s.textContent='.stg-ropes{position:absolute;left:0;bottom:-2px;width:100%;aspect-ratio:8/1;object-fit:fill;z-index:3;filter:drop-shadow(0 4px 6px rgba(0,0,0,.5))}';document.head.appendChild(s)}}catch(e){}
})();
